%求出距离中心点长度 
function length=lens(data,center,index) 
m=size(index); 
length=zeros(m(2),3); 
for i=1:m(2) 
 length(i,1)=sqrt((data(index(i),1)-center(1))^2+(data(index(i),2)-center(2))^2);%求出长度并保存 
 length(i,2)=data(index(i),3);%保存该点定价信息 
 length(i,3)=data(index(i),4);%保存该点完成状态 
end 
